mapper.sql:
WHERE e.tenant_id = #{tenantId}

    AND e.object_id IN

        #{oid}



    AND e.object_id = #{query.objectId}


    AND e.record_id = #{query.recordId}


    AND e.record_label = #{query.recordLabel}


    AND (
        e.record_label LIKE CONCAT('%', #{query.recordKeyword}, '%')
        OR e.record_id LIKE CONCAT('%', #{query.recordKeyword}, '%')
    )


    AND e.actor_id = #{query.actorId}


    AND e.event_type = #{query.eventType}


    AND e.source_type = #{query.sourceType}


    AND e.operation_id = #{query.operationId}


    AND e.correlation_id = #{query.correlationId}


    AND e.source_application_id = #{query.sourceApplicationId}


    AND e.flow_instance_id = #{query.flowInstanceId}


    AND e.task_id = #{query.taskId}


    AND e.config_key = #{query.configKey}


    AND e.change_reason IS NOT NULL AND e.change_reason != ''


    AND (e.change_reason IS NULL OR e.change_reason = '')


    AND e.occurred_at >= #{query.startTime}


    AND e.occurred_at <= #{query.endTime}


    AND EXISTS (
        SELECT 1
        FROM ai_data_audit_field f
        WHERE f.tenant_id = e.tenant_id
          AND f.event_id = e.id
          AND (
              f.field_code = #{query.fieldCode}
              OR f.column_name = #{query.fieldCode}
              OR LOWER(REPLACE(f.field_code, '_', '')) = LOWER(REPLACE(#{query.fieldCode}, '_', ''))
              OR LOWER(REPLACE(IFNULL(f.column_name, ''), '_', '')) = LOWER(REPLACE(#{query.fieldCode}, '_', ''))
          )
    )


    AND EXISTS (
        SELECT 1
        FROM ai_data_audit_field f
        WHERE f.tenant_id = e.tenant_id
          AND f.event_id = e.id
          AND (
              f.field_label LIKE CONCAT('%', #{query.fieldKeyword}, '%')
              OR f.field_code LIKE CONCAT('%', #{query.fieldKeyword}, '%')
          )
    )

mapper.select:
SELECT

FROM ai_data_audit_event
WHERE tenant_id = #{tenantId}
  AND id = #{id}
LIMIT 1
